<script setup>
import { onMounted, ref, reactive, inject, computed, watch, h, defineComponent } from "vue";
import axios from "axios";
import { useMeta } from "@/composables/use-meta";
import fuelEntryForm from "./components/fuelEntryForm.vue";
import Multiselect from "@suadelabs/vue3-multiselect";
import "@suadelabs/vue3-multiselect/dist/vue3-multiselect.css";
import { Modal } from 'bootstrap'
import bulkFilling from "./components/bulkFilling.vue";
import ApprovalChainModal from "../approvalChain/components/approvalChainModal.vue";
import NoteModal from "@/components/reusables/NoteModal.vue";

const openModalOnModal = inject('openModalOnModal');

const noteModalRef = ref(null);
const activeNoteRow = ref(null);

useMeta({ title: "Accounts Budgets" });
const exportProjectExpenseExcel = inject("exportProjectExpenseExcel");
const exportProjectExpenseItemsExcel = inject("exportProjectExpenseItemsExcel");
const exportProjectItemsExpenseByDateExcel = inject("exportProjectItemsExpenseByDateExcel");
const printProjectExpense = inject("printProjectExpense");
const printprojectExpenseItems = inject("printprojectExpenseItems");
const printProjectItemsExpenseByDate = inject("printProjectItemsExpenseByDate");
const add_entry = ref(false);
const showMessage = inject("showMessage");
const register_item_usage = ref(false);
const showError = inject("showError");
const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
const formatDate = inject("formatDate");
const formatNumber = inject("formatNumber");
const formatRate = inject("formatRate");
// const enforceMax = inject("enforceMax");
const tableShimmer = inject("tableShimmer");
const waitIndicator = inject("waitIndicator");
const loadingSpinner = inject("loadingSpinner");
const register_expense = ref(false);
const user_id = JSON.parse(localStorage.getItem("user")).id;
const loading_spinner = ref(false);
const expense_type  = ref('');
const expense_name = ref ('');
const bulkEntryId = ref(null);

const projectExpenseItemsColumns = ref(["sno", "description", "quantity", "initial", "final", "diff","target",  "date", "actions"]);

const table_option = ref({
  perPage: 20,
  perPageValues: [20, 51, 100],
  skin: "table table-hover table-striped",
  columnsClasses: { actions: "actions text-center" },
  sortable: ["SNo", "name", "short_name", "status"],
  sortIcon: {
    base: "sort-icon-none",
    up: "sort-icon-asc",
    down: "sort-icon-desc",
  },
  pagination: { nav: "scroll", chunk: 5 },
  texts: {
    count: "Showing {from} to {to} of {count}",
    filter: "",
    filterPlaceholder: "Search...",
    limit: "Results:",
  },
  resizableColumns: false,
});

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL,
});

const projectSearch = ref("");
const loadingProjects = ref(false);
const projects = ref([]);
const project = ref(null);
const searchedProjects = computed(() => {
  if (!projectSearch.value) return projects.value;
  const q = projectSearch.value.toLowerCase();
  return projects.value.filter(
    (p) =>
      p?.project_name?.toLowerCase().includes(q) || p.store_name?.toLowerCase().includes(q)
  );
});

const getProjects = async () => {
  try {
    const response = await axiosInstance.get("stores-projects");
    projects.value = response.data.map((item) => ({ ...item }));
  } catch (error) {
    showError(error.message);
    console.log(error);
  }
};

const assetGroups = ref([]);
const featchingAssets = ref(false);
const getAssetGroups = async () => {
  featchingAssets.value = true;
  try {
    const response = await axiosInstance.get("asset-groups");
    assetGroups.value = response.data.map((item) => ({ ...item }));
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    featchingAssets.value = false;
  }
};




const projectExpenses = ref([]);
const buildExpenseTree = (flatItems, parentId = null) => {
  return flatItems
    .filter((item) => (item.parent_id ?? null) === parentId)
    .map((item) => ({
      ...item,
      type: "item",
      name: item.item?.name || item.description,
      code:item.item?.code,
      description: item.description || item.item?.name || "-",
      unit: item.unit?.short_name || "-",
      quantity: formatNumber(item.quantity || 0),
      rate: formatRate(item.rate || 0),
      unformatedRate:item.rate,
      unformatedQty:item.quantity,
      children: buildExpenseTree(flatItems, item.id),
      cost: formatRate((item.rate || 0) * (item.quantity || 0)),
    }));
};


const collectAssetGroupItems = (nodes) => {
  let result = [];
  for (const node of nodes || []) {
    if (node.type === "item") {
      // only keep asset-group level items, don't descend into their nested asset children
      result.push(node);
    } else if (node.children?.length) {
      // keep descending through sub-entries to find their asset-group items
      result = result.concat(collectAssetGroupItems(node.children));
    }
  }
  return result;
};

const collectAllLeafItems = (nodes) => {
  let result = [];
  for (const node of nodes || []) {
    if (node.type === "item") {
      if (node.children?.length) {
        // has nested asset-level children — recurse into those instead of using this row
        result = result.concat(collectAllLeafItems(node.children));
      } else {
        result.push(node);
      }
    } else if (node.children?.length) {
      result = result.concat(collectAllLeafItems(node.children));
    }
  }
  return result;
};

const collectItems = (nodes) => {
  let result = [];
  for (const node of nodes || []) {
    if (node.type === "item") {
      result.push(node);
    }
    if (node.children?.length) {
      result = result.concat(collectItems(node.children));
    }
  }
  return result;
};

const buildEntryTree = (entries) => {
  return entries.map((entry) => ({
    id: entry.id,
    type: "entry",
    report: entry.report,
     quantity: entry.quantity,
    qty_used: entry.qty_used,
    qty_balance: entry.qty_balance,
    bulk_items: entry.bulk_items || [],
    description: entry.description || `Entry #${entry.id}`,
    children: [
      ...buildEntryTree(entry.children || []),   
      ...buildExpenseTree(entry.items || []),   
    ],
  }));
};

