    resetForm();
  } catch (error) {
    showError(error.message);
  } finally {
    loading.value = false;
  }
};


const deleteEntry = async (item) => {
  const res = await showConfirmation(
    "Delete Entry",
    `Are you sure you want to delete "${item.description}"?`,
    `/entries/${item.id}?deleted=1`,
    "put"
  );

  if (res?.refresh) {
    getProjectExpenses();
  }
};


const bulkRecord = ref([]);
const selectedOrder = ref('');
const bulkColumns = ref(['Sno', 'order', 'quantity', 'rate', 'date', 'actions']);

const openBulkModal = (arr) => {
  bulkRecord.value = (arr || []).map((item, index) => ({
    ...item,
    Sno: index + 1,
    order: item.source_id,
    rate: formatRate(item.rate),
  }));
  bootstrap.Modal.getOrCreateInstance(document.getElementById("bulk-list")).show();
};

const viewChain = (order) => {
  selectedOrder.value = order;
  openModalOnModal('approvalChainModal', 'bulk-list');
};

const openNote = (row) => {
  activeNoteRow.value = row;
  noteModalRef.value.open(null, row.id);
  openModalOnModal('note-modal', 'project-expenses-modal');
};


onMounted(() => {
  getProjects();
  const offcanvasElement = document.getElementById("offcanvasProjects");
  if (offcanvasElement) {
    const offcanvas = new bootstrap.Offcanvas(offcanvasElement);
    offcanvas.show();
  }
});
</script>

